def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    average_loss = (v1 + v2) / 2
    return {
        "value": average_loss,
        "trace": {
            "values": [v1, v2],
            "count": 2,
            "average_loss": average_loss,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
